def validate_synthesis_binding(stage):
    path = Path(stage) / VG_RELATIVE
    if hashlib.sha256(path.read_bytes()).hexdigest() != VG_SHA256:
        raise ValueError('Pitch/FIFO CDC scope: actual reviewed VG identity required')
    return dict(actual_reviewed_VG_sha256=VG_SHA256, serial_candidate_closures_inherited=False,
                c7_candidate_closures_inherited=False, chorus_candidate_closures_inherited=False)
